import PropTypes from "prop-types";
import Spacing, { propTypes as spacingPropTypes } from './Spacing';

function Card({children, ...spacingProps }) {
    return ( 
        <div className="mb-4 flex overflow-hidden rounded shadow-level1 bg-white">
            <Spacing {...spacingProps }>
                {children}
            </Spacing>
        </div>
    )
};

Card.propTypes = {
    ...spacingPropTypes,
    children: PropTypes.node,
};

export default Card;