import { useDispatch } from "react-redux";
import TradeCoinPage from "../../components/main/TradeCoinPage";
// import {createTransaction} from '../../actions/transactionActions';
import {createTransaction} from '../../actions/transactionPackActions';


function TradeCoinPageContainer(props) {
    const dispatch = useDispatch();

    const handleCreateTransaction = (...args) => {
        dispatch(createTransaction(...args));
    };

    return (
        <TradeCoinPage
            {...props}
            createTransaction={handleCreateTransaction}
        />
    );
}

export default TradeCoinPageContainer;




