import { SET_ERROR } from "../actions/transactionActions";
import { SHOW_NOTIFICATION, showMessage, hideMessage } from "../actions/notificationActions";
import { KEY, LIFECYCLE } from 'redux-pack';
import { FETCH_TRANSACTION_LIST } from '../actions/transactionPackActions';


export default function notificationEffects(store) {
    return function nextRunner(next) {
        return function actionRunner(action) {
            const { type, meta, payload } = action;
            const result = next(action);

            if (meta?.notification) {
                const { success, error } = meta.notification;
                const lifecycle = meta[KEY.LIFECYCLE];

                if (success && lifecycle === LIFECYCLE.SUCCESS) {
                    store.dispatch(showMessage(success));
                } else if ( error && lifecycle === LIFECYCLE.FAILURE) {
                    const errorMessage =
                        payload?.message ??
                        error;

                    store.dispatch(showMessage( errorMessage, true));
                }
            }


                // if( type === SET_ERROR ) {
                //     const errorMessage =
                //         payload?.errorMessage ??
                //         payload?.message ??
                //         (typeof payload === 'string' ? payload : null) ??
                //         '알 수 없는 오류가 발생했습니다.';

                //     store.dispatch(showMessage(errorMessage, true));

                // } else if ( type === FETCH_TRANSACTION_LIST && meta[KEY.LIFECYCLE] === LIFECYCLE.FAILURE ) {
                //     const errorMessage =
                //         payload?.response?.data?.errorMessage ??
                //         payload?.errorMessage ??
                //         payload?.message ??
                //         '거래 목록을 불러오지 못했습니다.';

                //     store.dispatch(showMessage(errorMessage, true));

                // } else if ( type ===FETCH_TRANSACTION_LIST && meta[KEY.LIFECYCLE] === LIFECYCLE.SUCCESS ) {
                //     store.dispatch(
                //         showMessage('거래 목록을 최신 정보로 업데이트하였습니다.')
                //     );
                // }

            return result;
        }
    }
}





