import React, { useCallback } from "react";
import { useNavigate } from "react-router-dom";

import InlineList from "../../modules/InlineList";
import Button from '../../modules/Button';
import Text from "../../modules/Text";
import Input from "../../modules/Input";
import Form from '../../modules/Form';
import Select, { Option } from "../../modules/Select";

import Api from '../../Api';
import { setTransactionList } from "../../actions/transactionActions";
import { requestTransactionList } from "../../actions/transactionActions";

function TransactionSearchFilter({
    // requestTransactionList,
    setFilter,
    searchParams,
    initValues
}) {
    const navigate = useNavigate();

    const handleSearch = (params) => {
        const cleanedParams = Object.entries(params)
            .filter(([, value]) => value !== '')
            .reduce(
                (obj, [key, value]) => ({
                    ...obj,
                    [key]: value,
                }),
                {}
            );

        // requestTransactionList(cleanedParams, 1);
        // setFilter(cleanedParams);

        const queryString = new URLSearchParams(
            Object.entries(cleanedParams).map(([key, value]) => [
                key,
                String(value),
            ])
        ).toString();
        setFilter(cleanedParams);
        navigate(queryString ? `/?${queryString}` : "/");
    };

        
    // const handleSubmit = useCallback(
    //     (params) => {
    //         const cleanedParams = Object.entries(params)
    //             .filter(([key, value]) => value !== "")
    //             .reduce((obj, [key, value]) => ({...obj, [key]: value}), {});

    //     requestTransactionList(cleanedParams);
    //     }, [requestTransactionList],
    // );

    
    return (
        <Form onSubmit={handleSearch} initValues={initValues}>
            <Form.Consumer>
                {({ onChange, values }) => (
                    <InlineList spacingBetween={2} verticalAlign="bottom">
                        <Text xlarge bold>
                            검색
                        </Text>
                        <Select
                            name="code"
                            label="코인 코드"
                            onChange={onChange}
                            value={values['code']}
                        >
                            <Option label="선택해주세요" />
                            <Option label="비트코인(BTX)" value="BTX"/>
                            <Option label="이더리움(ETH)" value="ETH"/>
                            <Option label="두잇코인(DOIT)" value="DOIT"/>
                        </Select>

                        <Input
                            name="currnetPrice_gte"
                            label="최소 거래가"
                            onChange={onChange}
                            value={values['currnetPrice_gte'] ?? ""}
                        />
                        <Input
                            name="currnetPrice_lte"
                            label="최대 거래가"
                            onChange={onChange}
                            value={values['currnetPrice_lte'] ?? ""}
                        />

                        <Button type="submit" primary>
                            검색
                        </Button>
                    </InlineList>
                )}
            </Form.Consumer>
        </Form>
    )
}

export default TransactionSearchFilter;


