export default function configureStoreFn(initStates) {
    return configureStore({
        reducer: reducers,
        preloadedState: initStates,

        middleware: (getDefaultMiddleware) =>
            getDefaultMiddleware({
                thunk:false,
                serializableCheck: {
                    ignoredActionPaths: [
                        'promise',
                        'meta.onSuccess',
                        'payload.headers',
                        'payload.config',
                        'payload.request',
                    ],
                },
            }).concat(
                thunk,
                reduxPackMiddleware,
                searchFilterEffects,
                notificationEffects,
                routerEffects,
                customMiddleware1,
                transactionEffects
            ),
            devTools: true,
        });
    }



