import { useSelector, useDispatch } from 'react-redux';

import TransactionPagination from '../../components/main/TransactionPagination';
import { requestTransactionList } from '../../actions/transactionPackActions';
import { 
    transactionListLoadingStateSelector,
    paginationSelector,
    transactionPagesSelector,
} from '../../selectors/transactionSelectors';


function TransactionPaginationContainer() {
    const dispatch = useDispatch();

    const { pagination, ids } = useSelector(
        (state) => state.transactions
    );

    const searchParams = useSelector(
        (state) => state.searchFilter.params
    );

    const { number, size } = pagination;

    const pageNumber = number || 1;
    const hasNext = ids.length === size;

    const loading = useSelector(
        transactionListLoadingStateSelector
    );
    
    const handleRequestTransactionList = (params, page) => {
        dispatch(requestTransactionList(params, page));
    };

    return (
        <TransactionPagination
            searchParams={searchParams}
            pageNumber={pageNumber}
            hasNext={hasNext}
            loading={loading}
            requestTransactionList={handleRequestTransactionList}
        />
    );
}

export default TransactionPaginationContainer;

