import PropTypes from "prop-types";

const headingTags = {
    1: 'h1',
    2: 'h2',
    3: 'h3',
    4: 'h4',
    5: 'h5',
    6: 'h6',
};

function Heading({
    children,
    invers = false,
    level = 1,
}) {
    const HeadingTag = headingTags[level] || 'h1';

    const levelStyles = {
        1: 'text-h1 mt-2 mb-4',
        2: 'text-h2 mt-2 mb-4',
        3: 'text-h3 mt-[6px] mb-3',
        4: 'text-xg mt-1 mb-2',
        5: 'text-md mt-1 mb-2',
        6: 'text-md mt-1 mb-1',
    }

    const className = [
        'font-bold leading-lg',
        levelStyles[level] || levelStyles[1],
        invers && 'text-white',
    ]
        .filter(Boolean)
        .join(' ');

    return (
        <HeadingTag className={className}>
            {children}
        </HeadingTag>
    );
}

Heading.propTypes = {
    children: PropTypes.node.isRequired,
    inverse: PropTypes.bool,
    level: PropTypes.number,
};

export default Heading;