import PropTypes from "prop-types";

function Text({
    children,
    bold = false,
    light = false,
    large = false,
    xlarge = false,
    small = false,
    xsmall = false,
    primary = false,
    secondary = false,
    inverse = false,
}) {
    const className = [
        'text-md leading-md font-normal text-default',
        xsmall && 'text-xs leading-xs',
        small && 'text-sm leading-sm',
        large && 'text-lg leading-lg',
        xlarge && 'text-xg leading-xg',
        secondary && 'text-secondary',
        primary && 'text-primary',
        bold && 'font-bold',
        light && 'font-light',
        inverse && 'text-white',
    ]
        .filter(Boolean)
        .join(' ');

    return <span className={className}>{children}</span>
}

Text.propTypes = {
    children: PropTypes.node.isRequired,
    bold: PropTypes.bool,
    light: PropTypes.bool,
    xsmall: PropTypes.bool,
    small: PropTypes.bool,
    large: PropTypes.bool,
    xlarge: PropTypes.bool,
    secondary: PropTypes.bool,
    primary: PropTypes.bool,
    inverse: PropTypes.bool,
};

export default Text;