import { SET_FILTER } from "../actions/searchFilterActions";
import { 
    requestTransactionList,
    resetTransactionList
} from "../actions/transactionPackActions";

const searchFilterEffects = (store) => (next) => (action) => {
    const result = next(action);

    if (action.type === SET_FILTER) {
        const { params = {} } = action.payload || {};

        store.dispatch(resetTransactionList());
        store.dispatch(requestTransactionList(params, 1));
    }

    return result;
}

export default searchFilterEffects;