import { FETCH_LIST, CREATE, UPDATE, DELETE, FETCH, RESET } from "./actionTypes";
import Api from "../../Api";

const createResourceActions = ( resourceName, key = "id") => {
    const createMeta = (meta ={}) => ({
        ...meta,
        key,
        resourceName,
    })

    return {
        collection: ( params = {}, meta={}) => ({
            type:FETCH_LIST,
            promise:Api.get(resourceName, {params}),
            meta:createMeta(meta),
        }),

        member: (id, params = {}, meta = {}) => ({
            type: FETCH,
            promise: Api.get(`${resourceName}/${id}`, { params }),
            meta: createMeta(meta),
        }),

        create: (data, params = {}, meta = {}) => ({
            type: CREATE,
            promise: Api.post(resourceName, data, { params }),
            meta: createMeta(meta),
        }),

        update: (id, data, params = {}, meta = {}) => ({
            type: UPDATE,
            promise: Api.put(`${resourceName}/${id}`, data, {
                params,
            }),
            meta: createMeta(meta),
        }),

        destroy: (id, params = {}, meta = {}) => ({
            type: DELETE,
            promise: Api.delete(`${resourceName}/${id}`, {
                params,
            }),
            payload: { id },
            meta: createMeta(meta),
        }),

        reset: () => ({
            type: RESET,
            meta: { resourceName },
        }),
    };
};

export default createResourceActions;