import { createSelector } from "@reduxjs/toolkit";

import {
    CREATE,
    UPDATE,
    FETCH_LIST,
    FETCH,
} from "./actionTypes";

export default function createSelectors(resourceName) {
    const resourceSelector = (state) => state[resourceName];

    const entitiesSelector = (state) =>
        resourceSelector(state)?.entities ?? {};

    const pagesSelector = (state) =>
        resourceSelector(state)?.pages ?? {};

    const idSelector = (state) =>
        resourceSelector(state)?.id;

    const entitySelector = createSelector(
        [idSelector, entitiesSelector],
        (id, entities) => (id == null ? undefined : entities[id])
    );

    const collectionSelector = createSelector(
        [entitiesSelector, pagesSelector],
        (entities, pages) => {
            const ids = [...new Set(
                Object.values(pages).flat()
            )];

            return ids
                .map((id) => entities[id])
                .filter(Boolean);
        }
    );

    const loadingStateSelector = (state) =>
        resourceSelector(state)?.loadingState ?? {};

    const errorStateSelector = (state) =>
        resourceSelector(state)?.errorState ?? {};

    const collectionLoadingStateSelector = (state) =>
        loadingStateSelector(state)[`${FETCH_LIST}/${resourceName}`] ?? false;

    const createLoadingStateSelector = (state) =>
        loadingStateSelector(state)[`${CREATE}/${resourceName}`] ?? false;

    const updateLoadingStateSelector = (state) =>
        loadingStateSelector(state)[`${UPDATE}/${resourceName}`] ?? false;

    const memberLoadingStateSelector = (state) =>
        loadingStateSelector(state)[`${FETCH}/${resourceName}`] ?? false;

    const collectionErrorStateSelector = (state) =>
        errorStateSelector(state)[`${FETCH_LIST}/${resourceName}`] ?? false;

    const createErrorStateSelector = (state) =>
        errorStateSelector(state)[`${CREATE}/${resourceName}`] ?? false;

    const updateErrorStateSelector = (state) =>
        errorStateSelector(state)[`${UPDATE}/${resourceName}`] ?? false;

    const memberErrorStateSelector = (state) =>
        errorStateSelector(state)[`${FETCH}/${resourceName}`] ?? false;

    const paginationSelector = createSelector(
        [
            (state) => resourceSelector(state)?.pagination?.number,
            (state) => resourceSelector(state)?.pagination?.size,
        ],
        (number, size) => ({
            number: number ?? 0,
            size,
        })
    );

    return {
        resourceSelector,
        entitySelector,
        entitiesSelector,
        pagesSelector,
        collectionSelector,
        collectionLoadingStateSelector,
        collectionErrorStateSelector,
        createLoadingStateSelector,
        createErrorStateSelector,
        updateLoadingStateSelector,
        updateErrorStateSelector,
        memberLoadingStateSelector,
        memberErrorStateSelector,
        paginationSelector,
    };
}