import React, { PureComponent } from "react";
import PropTypes from "prop-types";

import Text from "../../modules/Text";
import Spacing from "../../modules/Spacing";
import Input from "../../modules/Input";
import Button from "../../modules/Button";
import InlineList from "../../modules/InlineList";
import Form from "../../modules/Form";
import { Consumer as Modal } from "../../modules/modal/context";

function RegisterPage({ name = "", createUser, loading = false }) {
    const handleSubmit = async (values, closeModal) => {
        const formValues = {
            ...values,
            name,
        };

        try {
            await createUser(formValues);
            closeModal();
        } catch (error) {
            console.error("회원 등록에 실패했습니다.", error);
        }
    };

    return (
        <Modal>
            {({ closeModal }) => (
                <Form
                    onSubmit={(values) =>
                        handleSubmit(values, closeModal)
                    }
                >
                    <Form.Consumer>
                        {({ onChange }) => (
                            <Spacing horizontal={4} vertical={8}>
                                <Text xlarge bold>
                                    회원 등록
                                </Text>

                                <Spacing bottom={2}>
                                    <Input
                                        name="userId"
                                        label="사용자 아이디"
                                        onChange={onChange}
                                    />
                                </Spacing>

                                <Spacing bottom={2}>
                                    <Input
                                        name="totalAmount"
                                        type="number"
                                        label="자산 총액"
                                        onChange={onChange}
                                    />
                                </Spacing>

                                <InlineList spacingBetween={1}>
                                    <Button
                                        type="submit"
                                        primary
                                        disabled={loading}
                                    >
                                        {loading
                                            ? "등록 중..."
                                            : "회원 등록"}
                                    </Button>

                                    <Button
                                        onPress={closeModal}
                                        disabled={loading}
                                    >
                                        취소
                                    </Button>
                                </InlineList>
                            </Spacing>
                        )}
                    </Form.Consumer>
                </Form>
            )}
        </Modal>
    );
}

RegisterPage.propTypes = {
    createUser: PropTypes.func.isRequired,
    loading: PropTypes.bool,
    name: PropTypes.string,
};

export default RegisterPage;