import { handle } from "redux-pack";

import {
    CREATE,
    UPDATE,
    FETCH,
    FETCH_LIST,
    RESET,
} from "./actionTypes";

export default (...reducerName) => {
    return reducerName.reduce((apiReducers, name) => {
        const createActionState = () => ({
            [`${CREATE}/${name}`]: false,
            [`${UPDATE}/${name}`]: false,
            [`${FETCH}/${name}`]: false,
            [`${FETCH_LIST}/${name}`]: false,
        });

        const initState = {
            ids: [],
            entities: {},
            loadingState: createActionState(),
            errorState: createActionState(),
            pagination: {},
            pages: {},
        };

        apiReducers[name] = (state = initState, action) => {
            const { type, payload, meta } = action;
            const { resourceName, key = "id"} = meta || {};

            if ( type === RESET && resourceName === name ) {
                 return initState;
            }

            if ( 
                resourceName !== name || 
                ![CREATE, UPDATE, FETCH, FETCH_LIST].includes(type)
            ) {
                return state;
            }

            return handle(state, action, {
                start: ( prevState )=> ({
                    ...prevState,
                    loadingState: {
                        ...prevState.loadingState,
                        [`${type}/${name}`]: true,
                    },
                    errorState: {
                        ...prevState.errorState,
                        [`${type}/${name}`]: false,
                    },
                }),

                success: (prevState) => {
                    // Axios 응답 객체와 직접 전달된 데이터 모두 지원
                    const data = payload?.data ?? payload;

                    const loadingState = {
                        ...prevState.loadingState,
                        [`${type}/${name}`]: false,
                    };

                    const errorState = {
                        ...prevState.errorState,
                        [`${type}/${name}`]: false,
                    };

                    if (type === FETCH_LIST) {
                        const list = Array.isArray(data) ? data : [];

                        const ids = list.map((entity) => entity[key]);

                        const entities = list.reduce(
                            (result, entity) => ({
                                ...result,
                                [entity[key]]: entity,
                            }),
                            {}
                        );

                        const pageNumber = meta?.pageNumber ?? 1;
                        const pageSize = meta?.pageSize ?? list.length;

                        return {
                            ...prevState,
                            ids,
                            entities: {
                                ...prevState.entities,
                                ...entities,
                            },
                            loadingState,
                            errorState,
                            pagination: {
                                ...prevState.pagination,
                                number: pageNumber,
                                size: pageSize,
                            },
                            pages: {
                                ...prevState.pages,
                                [pageNumber]: ids,
                            },
                        };
                    }

                    // 생성, 수정, 단건 조회
                    const entity = data;

                    if (!entity || entity[key] == null) {
                        return {
                            ...prevState,
                            loadingState,
                            errorState,
                        };
                    }

                    const id = entity[key];

                    return {
                        ...prevState,
                        ids: prevState.ids.includes(id)
                            ? prevState.ids
                            : [...prevState.ids, id],
                        entities: {
                            ...prevState.entities,
                            [id]: entity,
                        },
                        loadingState,
                        errorState,
                    };
                },

                failure: (prevState) => {
                    const errorMessage =
                        payload?.response?.data?.errorMessage ??
                        payload?.message ??
                        "요청 처리 중 오류가 발생했습니다.";

                    return {
                        ...prevState,
                        loadingState: {
                            ...prevState.loadingState,
                            [`${type}/${name}`]: false,
                        },
                        errorState: {
                            ...prevState.errorState,
                            [`${type}/${name}`]: errorMessage,
                        },
                    };
                },
            });
        };

        return apiReducers;
    }, {});
};