import React from "react";

import Heading from "../../modules/Heading";
import Button from '../../modules/Button';
import Card from "../../modules/Card";
import InlineList from '../../modules/InlineList';
import Text from "../../modules/Text";

import { Consumer as Modal } from "../../modules/modal/context";
import { TRADE_COIN_MODAL } from "../../constants/modals";

function CoinDashlet({name, priceLabel}) {
    return (
        <Modal>
            {({ openModal }) => (
            <Card vertical={4} horizontal={4}>
                <Heading level={4}>
                    {name}
                    <Text>{priceLabel}</Text>
                </Heading>

                <InlineList spacingBetween={1}>
                    <Button
                        primary
                        small
                        onPress={() =>
                        openModal(TRADE_COIN_MODAL, {
                            type: "sell",
                            name,
                            price: priceLabel,
                        })
                        }
                    >
                        매도
                    </Button>

                    <Button
                        small
                        onPress={() =>
                        openModal(TRADE_COIN_MODAL, {
                            type: "buy",
                            name,
                            price: priceLabel,
                        })
                        }
                    >
                        매수
                    </Button>
                </InlineList>
            </Card>
            )}
        </Modal>
    )
}

export default CoinDashlet;