import React, { useRef, useEffect } from "react";

function Input({
    errorMessage,
    label,
    value = "",
    name,
    type = "text",
    large = false,
    xlarge = false,
    small = false,
    xsmall = false,
    onChange = () => {},
    autoFocus = false,
    className = "",
}) {
    const inputRef = useRef(null);

    useEffect(() => {
        if(autoFocus && inputRef.current) {
            inputRef.current.focus();
        }
    }, [autoFocus]);

    const handleChange = (e) => {
        onChange(name, e.target.value);
    };

    const sizeStyles = xsmall
        ? "text-xs p-1"
        : small
        ? "text-sm p-2"
        : large
        ? "text-lg p-1.5"
        : xlarge
        ? "text-xl p-1.5"
        : "text-base p-1.5";

    const inputType = type === "price" ? "text" : type;

    return (
        <fieldset className="relative border-0 p-0">
            <label
                htmlFor={`input_${name}`}
                className = {`block cursor-pointer text-xs ${errorMessage ? "text-red-500" : "text-gray-700"}`}
            >
                {errorMessage || label}
            </label>

            <input
                ref={inputRef}
                id={`input_${name}`}
                name={name}
                type={inputType}
                value={value ?? ""}
                onChange={handleChange}
                className={`
                        mt-0.5 w-full rounded border border-solid
                        border-blue-600 outline-none
                        focus:ring-2 focus:ring-black/30
                        ${sizeStyles}
                        ${errorMessage ? "border-red-500":""}
                        ${className}
                    `}
            >
            </input>
        </fieldset>
    )
}

export default Input;