import React from "react";
import { useDispatch } from "react-redux";

import Text from "../../modules/Text";
import Spacing from '../../modules/Spacing';
import Input from "../../modules/Input";
import Button from "../../modules/Button";
import InlineList from "../../modules/InlineList";
import Form from '../../modules/Form';
import { Consumer as Modal } from '../../modules/modal/context';
// import { createTransaction } from "../../actions/transactionActions";

function TradeCoinPage( { name, code, price, type, createTransaction, loading}) {
    // const dispatch = useDispatch();

    const handleSubmit = (values, closeModal) => {
        const formValues = {
            ...values,
            code,
            name,
            type,
        };

       createTransaction(formValues, closeModal);

    };

    const typeName = type === "sell" ? "판매" : "구매";

    return (
        <Modal>
            {({ closeModal }) => (
                <Form
                    onSubmit={(values) => handleSubmit(values, closeModal)}
                    initValues={{ currentPrice:price}}
                >
                    <Form.Consumer>
                        {({ onChange, values}) => (
                            <Spacing horizontal={4} vertical={8}>
                                <Text xlarge bold>
                                    {name} {typeName}
                                </Text>

                                <Spacing bottom={2}>
                                    <Input
                                        name="currentPrice"
                                        label="금액"
                                        value={values.currentPrice ?? ""}
                                        onChange={onChange}
                                    />
                                </Spacing>

                                <Spacing bottom={2}>
                                    <Input
                                        name="amount"
                                        label="수량"
                                        value={values.amount ?? ""}
                                        onChange={onChange}
                                    />
                                </Spacing>

                                <InlineList spacingBetween={1}>
                                    <Button primary type="submit" disabled={loading}>
                                        {loading ? '거래 처리중' : typeName}
                                    </Button>
                                    <Button onPress={closeModal} disabled={loading}>
                                        취소
                                    </Button>
                                </InlineList>
                            </Spacing>
                        )}
                    </Form.Consumer>
                </Form>
            )}
        </Modal>
    )
}

export default TradeCoinPage;
