import React from "react"; 

import Heading from "../modules/Heading";
import Text from '../modules/Text';
import Button from "../modules/Button";
import { Consumer as Modal } from '../modules/modal/context';
import { REGISTER_USER_MODAL } from "../constants/modals";

export const HEIGHT = 64;

function AppNav() {
    return (
        <div
            className="fixed left-0 top-0 z-50 flex h-[60px] w-full flex-col justify-center bg-blue-600 shadow-md"
        >
            <div
                className="flex items-center justify-between px-2"
            >
                <Heading level={3} inverse>
                    두잇 코인 거래소
                </Heading>
                {/* <Text inverse bold large> */}
                    {/* 회원 가입 */}
                {/* </Text> */}
                <Modal>
                    {({ openModal }) => (
                        <Button inverse bold large onPress={() => openModal(REGISTER_USER_MODAL)}>
                            회원가입
                        </Button>
                    )}
                </Modal>
            </div>
        </div>
    )
}

export default AppNav;