import { useCallback } from "react";
import { useSelector, useDispatch } from 'react-redux';

import TransactionList from '../../components/main/TransactionList';
//import { setTransactionList } from '../../actions/transactionActions';
import { requestTransactionList, FETCH_TRANSACTION_LIST } from '../../actions/transactionPackActions';

import { transactionListSelector, transactionListLoadingStateSelector } from "../../selectors/transactionSelectors";

function ConnectedTransactionList(props) {
    const dispatch = useDispatch();

    // const { ids, entities, loadingState } = useSelector(
    //     (state) => state.transactions
    // );

    // const transactions = ids.map((id) => entities[id]);
    // const loading = Boolean(loadingState?.[FETCH_TRANSACTION_LIST]);
    const transactions = useSelector(transactionListSelector);

    const loading = useSelector(
        transactionListLoadingStateSelector
    );

    const handleRequestTransactionList = (...args) => {
        dispatch(requestTransactionList(...args));
    };

    return (
        <TransactionList
            {...props}
            transactions={transactions}
            loading={loading}
            requestTransactionList={handleRequestTransactionList}
            //setTransactionList={handleSetTransactionList}
        />
    );
}

export default ConnectedTransactionList;


