import PropTypes from "prop-types";

export const propTypes = {
    top: PropTypes.number,
    left: PropTypes.number,
    right: PropTypes.number,
    bottom: PropTypes.number,
    vertical: PropTypes.number,
    horizontal: PropTypes.number,
    children: PropTypes.node,
}

function Spacing({
    children,
    top,
    left,
    right,
    bottom,
    vertical,
    horizontal,
}) {
    const computedTop = top?? vertical;
    const computedBottom = bottom ?? vertical;
    const computedLeft = left ?? horizontal;
    const computedRight = right ?? horizontal;

    const computedStyles = {
        flex: 1,
        ...(computedTop != null && {
            marginTop: computedTop *4
        }),
        ...(computedBottom != null && {
            marginBottom: computedBottom * 4,
        }),
        ...(computedLeft != null && {
            marginLeft: computedLeft * 4,
        }),
        ...(computedRight != null && {
            marginRight: computedRight * 4,
        }),
    };

    return <div style={computedStyles}>{children}</div>
}

Spacing.propTypes = propTypes;

export default Spacing;