import React, {useState, useRef, useEffect } from "react";
import Option from './Option';

export { Option };

function Select({
    children,
    disabled = false,
    errorMessage,
    label,
    value = "",
    name,
    large = false,
    xlarge = false,
    small = false,
    xsmall = false,
    onChange = () => {},
    autoFocus = false,
    className = "",
}) {
    const selectRef = useRef(null);
    const [focused, setFocused] = useState(false);

    useEffect(() => {
        if(autoFocus && selectRef.current) {
            selectRef.current.focus();
        }
    }, [autoFocus]);

    const handleChange = (e) => {
        onChange(name, e.target.value);
    };

    const sizeStyles = xsmall
        ? "text-xs"
        : small
        ? "text-sm"
        : large
        ? "text-lg"
        : xlarge
        ? "text-xl"
        : "text-base";

    const paddingStyles = xsmall
        ? "p-1.5"
        : small
        ? "p-1"
        : large || xlarge
        ? "p-2"
        : "p-1.5";

    return(
        <fieldset className="relative border-0 p-0">
            <label
                htmlFor={`input_${name}`}
                className={`block cursor-pointer text-xs ${errorMessage ? "text-red-500" : "text-gray-700"}`}
            >
                {errorMessage || label}
            </label>

            <div
                className={`
                    mt-0.5 rounded border border-solid
                    ${paddingStyles}
                    ${errorMessage ? "border-red-500" : "border-blue-600"}
                    ${focused ? "ring-2 ring-black/30" : ""}
                    ${disabled ? "cursor-not-allowed bg-gray-100 opacity-60" : ""}
                    ${className}
                `}    
            >
                <select
                    ref={selectRef}
                    id={`input_${name}`}
                    name={name}
                    disabled={disabled}
                    value={value ?? ""}
                    onChange={handleChange}
                    onFocus={() => setFocused(true)}
                    onBlur={() => setFocused(false)}
                    className={`
                        w-full border-0 bg-white outline-none
                        disabled:cursor-not-allowed
                        ${sizeStyles}
                    `}
                >
                    {React.Children.map(children, (child) => {
                        if ( !React.isValidElement(child)) {
                            return child;
                        }

                        return React.cloneElement(child, { disabled});
                    })}
                </select>
            </div>
        </fieldset>
    )
}

export default Select;