import { useSelector, useDispatch } from "react-redux";

import TransactionSearchFilter from '../../components/main/TransactionSearchFilter';
import { setTransactionList } from '../../actions/transactionActions';
// import { requestTransactionList } from "../../actions/transactionActions";
import { requestTransactionList } from "../../actions/transactionPackActions";
import { setFilter } from "../../actions/searchFilterActions";


function TransactionSearchFilterContainer(props) {
    const dispatch = useDispatch();

    const searchParams = useSelector(
        (state) => state.searchFilter.params
    );

    const initValues = useSelector(
        (state) => state.searchFilter?.params ?? {}
    );

    const handleRequestTransactionList = (params, _page = 1) => {
        dispatch(requestTransactionList(params, _page));
    };

    const handleSetFilter = (params) => {
        dispatch(setFilter(params));
    };

    return (
        <TransactionSearchFilter
            {...props}
            initValues={initValues}
            requestTransactionList={handleRequestTransactionList}
            setFilter={handleSetFilter}
            searchParams={searchParams}
        />
    );
}

export default TransactionSearchFilterContainer;



