import React from "react";

function Button({
    children,
    disabled = false,
    xsmall = false,
    small = false,
    large = false,
    xlarge = false,
    secondary = false,
    primary = false,
    type = "button",
    onPress = () => {},
    className = "",
}) {
    const baseStyles = 
        "border border-solid rounded font-bold outline-none cursor-pointer" +
        "shadow-sm transition-colors" +
        "hover:bg-gray-100 focus:ring-2 focus:ring-black/30" +
        "disabled:cursor-not-allowed disabled:opacity-50";

    const sizeStyles = xsmall
        ? "text-xs p-1"
        : small
        ? "text-sm p-1.5"
        : large
        ? "text-lg p-2.5"
        : xlarge
        ? "text-xl p-2.5"
        : "text-base px-4 py-2";

    const variantStyles = primary
        ? "border-blue-600 bg-blue-600 text-white hover:bg-blue-700"
        : secondary
        ? "border-gray-500 text-gray-600 hover:bg-gray-100"
        : "border-gray-400 text-gray-700";

    const disabledStyles = disabled
        ? "border-gray-400 bg-gray-200 text-gray-400 hover:bg-gray-200"
        : "";
        
    return (
        <button
            type={type}
            disabled={disabled}
            onClick={onPress}
            className={`${baseStyles} ${sizeStyles} ${variantStyles} ${disabledStyles} ${className}`}
        >
            {children}
        </button>
    );
}

export default Button;
